                    for r in prims.iter_mut() {
                        if r.get(3).map(String::as_str) == Some(old.as_str()) {
                            r[3] = g.clone();
                            touched = true;
                        }
                    }
                    if touched {
                        let _ = db_write("/etc/passwd", &prims);
                    }
