                let user = nf
                    .first()
                    .map(|s| String::from(**s))
                    .unwrap_or_else(|| {
                        user_name(ustd::getuid())
                            .unwrap_or_else(|| String::from("root"))
                    });
                let pw = nf
                    .get(1)
                    .map(|s| String::from(**s))
                    .unwrap_or_else(|| String::from("x"));
