                let Some(ri) = rows.iter().position(|r| {
                    r.first().map(String::as_str) == Some(user.as_str())
                }) else {
                    self.fail(&alloc::format!("passwd: no such user '{}'", user));
                    return;
                };
                while rows[ri].len() < 2 {
                    rows[ri].push(String::new());
                }
